function linearSearch(nums, target) {
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] === target) {
      return i;
    }
  }
  return -1;
}

function binarySearch(nums, target) {
  let lo = 0;
  let hi = nums.length - 1;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (nums[mid] === target) {
      return mid;
    } else if (nums[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return -1;
}

function bubbleSort(nums) {
  const n = nums.length;
  for (let i = 0; i < n - 1; i++) {
    for (let j = 0; j < n - 1 - i; j++) {
      if (nums[j] > nums[j + 1]) {
        [nums[j], nums[j + 1]] = [nums[j + 1], nums[j]];
      }
    }
  }
}

function selectionSort(nums) {
  const n = nums.length;
  for (let i = 0; i < n - 1; i++) {
    let min = i;
    for (let j = i + 1; j < n; j++) {
      if (nums[j] < nums[min]) {
        min = j;
      }
    }
    [nums[i], nums[min]] = [nums[min], nums[i]];
  }
}

function insertionSort(nums) {
  for (let i = 1; i < nums.length; i++) {
    const key = nums[i];
    let j = i - 1;
    while (j >= 0 && nums[j] > key) {
      nums[j + 1] = nums[j];
      j--;
    }
    nums[j + 1] = key;
  }
}

function mergeSort(nums) {
  if (nums.length <= 1) {
    return nums;
  }
  const mid = Math.floor(nums.length / 2);
  const left = mergeSort(nums.slice(0, mid));
  const right = mergeSort(nums.slice(mid));
  return merge(left, right);
}

function merge(left, right) {
  const result = [];
  let i = 0;
  let j = 0;
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.push(left[i]);
      i++;
    } else {
      result.push(right[j]);
      j++;
    }
  }
  return result.concat(left.slice(i)).concat(right.slice(j));
}

function quickSort(nums, low, high) {
  if (low < high) {
    const p = partition(nums, low, high);
    quickSort(nums, low, p - 1);
    quickSort(nums, p + 1, high);
  }
}

function partition(nums, low, high) {
  const pivot = nums[high];
  let i = low - 1;
  for (let j = low; j < high; j++) {
    if (nums[j] < pivot) {
      i++;
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  }
  [nums[i + 1], nums[high]] = [nums[high], nums[i + 1]];
  return i + 1;
}

function heapSort(nums) {
  const n = nums.length;
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
    siftDown(nums, i, n);
  }
  for (let i = n - 1; i > 0; i--) {
    [nums[0], nums[i]] = [nums[i], nums[0]];
    siftDown(nums, 0, i);
  }
}

function siftDown(nums, root, size) {
  while (true) {
    let largest = root;
    const left = 2 * root + 1;
    const right = 2 * root + 2;
    if (left < size && nums[left] > nums[largest]) {
      largest = left;
    }
    if (right < size && nums[right] > nums[largest]) {
      largest = right;
    }
    if (largest === root) {
      return;
    }
    [nums[root], nums[largest]] = [nums[largest], nums[root]];
    root = largest;
  }
}

class Graph {
  constructor() {
    this.edges = new Map();
  }

  addEdge(from, to) {
    if (!this.edges.has(from)) this.edges.set(from, []);
    if (!this.edges.has(to)) this.edges.set(to, []);
    this.edges.get(from).push(to);
    this.edges.get(to).push(from);
  }
}

function bfs(graph, start) {
  const visited = new Set([start]);
  const queue = [start];
  const order = [];
  while (queue.length > 0) {
    const node = queue.shift();
    order.push(node);
    for (const neighbor of graph.edges.get(node) || []) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push(neighbor);
      }
    }
  }
  return order;
}

function dfs(graph, start) {
  const visited = new Set();
  const order = [];
  dfsVisit(graph, start, visited, order);
  return order;
}

function dfsVisit(graph, node, visited, order) {
  if (visited.has(node)) {
    return;
  }
  visited.add(node);
  order.push(node);
  for (const neighbor of graph.edges.get(node) || []) {
    dfsVisit(graph, neighbor, visited, order);
  }
}

class WeightedGraph {
  constructor() {
    this.edges = new Map();
  }

  addEdge(from, to, weight) {
    if (!this.edges.has(from)) this.edges.set(from, []);
    if (!this.edges.has(to)) this.edges.set(to, []);
    this.edges.get(from).push({ to, weight });
    this.edges.get(to).push({ to: from, weight });
  }
}

function dijkstra(graph, start, nodes) {
  const dist = new Map(nodes.map((node) => [node, Infinity]));
  const visited = new Set();
  dist.set(start, 0);

  while (visited.size < nodes.length) {
    const current = closestUnvisited(dist, visited);
    if (current === null) {
      break;
    }
    visited.add(current);
    for (const edge of graph.edges.get(current) || []) {
      const newDist = dist.get(current) + edge.weight;
      if (newDist < dist.get(edge.to)) {
        dist.set(edge.to, newDist);
      }
    }
  }
  return dist;
}

function closestUnvisited(dist, visited) {
  let best = null;
  let bestDist = Infinity;
  for (const [node, d] of dist) {
    if (!visited.has(node) && d < bestDist) {
      best = node;
      bestDist = d;
    }
  }
  return best;
}
